sys_script_include.script:
var BNB_Verifica_Duplicidade_Certificado = Class.create();
BNB_Verifica_Duplicidade_Certificado.prototype = Object.extendsObject(
  global.AbstractAjaxProcessor,
  {
    checkDuplicate: function () {
      var grCertificate = new GlideRecord("cmdb_ci_certificate");

      var serial = this.getParameter("sysparm_serial_number");
      var fingerprint = this.getParameter("sysparm_fingerprint");
      var result = {
        type: "",
        serial_number: serial ? serial + "" : "",
        fingerprint: fingerprint ? fingerprint + "" : "",
        formatted: "",
        status: "ERROR",
        message: "BNB_VerificaDuplicidade_Certificado - Parâmetro inválido.",
      };

      result = this.formatNumber(result);
      if (result.status == "OK") {
        var field =
          result.type == "Serial Number" ? "serial_number" : "fingerprint";
        if (grCertificate.get(field, result.formatted)) {
          result.status = "ERROR";
          result.message = "Certificado com esse " + result.type + " já existe";
        }
      }
      return JSON.stringify(result);
    },

    // Verifica validade e formata numero
    formatNumber: function (result) {
      result.status = "ERROR";
      var number;
      var regexp;
      if (result.serial_number) {
        number = result.serial_number;
        result.type = "Serial Number";
        regexp = /^[A-F0-9]{2,40}$/;
      } else if (result.fingerprint) {
        number = result.fingerprint;
        result.type = "Fingerprint";
        regexp = /^[A-F0-9]{64}$/;
      }
      if (!number) {
        result.message = "inválido. Não pode ser vazio.";
        return result;
      }
      var normalized = number.replace(/[\s:]/g, "").toUpperCase();
      if (normalized.length % 2 != 0) {
        result.message =
          result.type + " inválido. Deve ter um número par de caracteres.";
      } else if (!regexp.test(normalized)) {
        result.message =
          result.type == "Fingerprint"
            ? "Fingerprint inválido. Deve ter 64 caracteres hexadecimais (SHA-256)."
            : "Serial Number inválido. Deve ter até 40 caracteres hexadecimais.";
      } else {
        result.formatted = normalized.match(/.{2}/g).join(" ");
        result.status = "OK";
      }
      return result;
    },

    type: "BNB_Verifica_Duplicidade_Certificado",
  },
);
